#include <charconv>
#include <cstdint>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

struct Version
{
    std::uint64_t major, minor, patch;
    std::vector<std::string> prerelease;
    std::vector<std::string> build;
};

namespace
{
    bool allDigits(std::string_view s)
    {
        if (s.empty()) return false;
        for (char c : s) if (c < '0' || c > '9') return false;
        return true;
    }

    bool identifierChars(std::string_view s)
    {
        if (s.empty()) return false;
        for (char c : s)
            if (!((c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '-')) return false;
        return true;
    }

    std::optional<std::vector<std::string>> identifiers(std::string_view s, bool numericNoLeadingZero)
    {
        std::vector<std::string> out;
        std::size_t start{ 0 };
        for (;;)
        {
            const std::size_t dot{ s.find('.', start) };
            const std::string_view part{ s.substr(start, dot == std::string_view::npos ? std::string_view::npos : dot - start) };
            if (!identifierChars(part)) return std::nullopt;
            if (numericNoLeadingZero && allDigits(part) && part.size() > 1 && part[0] == '0') return std::nullopt;
            out.emplace_back(part);
            if (dot == std::string_view::npos) break;
            start = dot + 1;
        }
        return out;
    }

    std::optional<std::uint64_t> number(std::string_view s)
    {
        if (!allDigits(s) || (s.size() > 1 && s[0] == '0')) return std::nullopt;
        std::uint64_t value{ 0 };
        const auto [ptr, ec] { std::from_chars(s.data(), s.data() + s.size(), value) };
        if (ec != std::errc{} || ptr != s.data() + s.size()) return std::nullopt;
        return value;
    }

    int compareIdentifiers(const std::string& a, const std::string& b)
    {
        const bool na{ allDigits(a) };
        const bool nb{ allDigits(b) };
        if (na && nb)
        {
            if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
            return a < b ? -1 : (a > b ? 1 : 0);
        }
        if (na) return -1;
        if (nb) return 1;
        return a < b ? -1 : (a > b ? 1 : 0);
    }

    std::string joined(const std::vector<std::string>& parts)
    {
        std::string out;
        for (std::size_t i{ 0 }; i < parts.size(); ++i)
        {
            if (i > 0) out += '.';
            out += parts[i];
        }
        return out;
    }
}

std::optional<Version> parseVersion(std::string_view text)
{
    Version v{};
    const std::size_t plus{ text.find('+') };
    if (plus != std::string_view::npos)
    {
        const auto build{ identifiers(text.substr(plus + 1), false) };
        if (!build) return std::nullopt;
        v.build = *build;
        text = text.substr(0, plus);
    }
    const std::size_t dash{ text.find('-') };
    if (dash != std::string_view::npos)
    {
        const auto pre{ identifiers(text.substr(dash + 1), true) };
        if (!pre) return std::nullopt;
        v.prerelease = *pre;
        text = text.substr(0, dash);
    }
    const std::size_t dot1{ text.find('.') };
    if (dot1 == std::string_view::npos) return std::nullopt;
    const std::size_t dot2{ text.find('.', dot1 + 1) };
    if (dot2 == std::string_view::npos) return std::nullopt;
    const auto major{ number(text.substr(0, dot1)) };
    const auto minor{ number(text.substr(dot1 + 1, dot2 - dot1 - 1)) };
    const auto patch{ number(text.substr(dot2 + 1)) };
    if (!major || !minor || !patch) return std::nullopt;
    v.major = *major;
    v.minor = *minor;
    v.patch = *patch;
    return v;
}

int compareVersions(const Version& a, const Version& b)
{
    if (a.major != b.major) return a.major < b.major ? -1 : 1;
    if (a.minor != b.minor) return a.minor < b.minor ? -1 : 1;
    if (a.patch != b.patch) return a.patch < b.patch ? -1 : 1;
    if (a.prerelease.empty() || b.prerelease.empty())
    {
        if (a.prerelease.empty() && b.prerelease.empty()) return 0;
        return a.prerelease.empty() ? 1 : -1;
    }
    for (std::size_t i{ 0 }; i < a.prerelease.size() && i < b.prerelease.size(); ++i)
        if (const int c{ compareIdentifiers(a.prerelease[i], b.prerelease[i]) }; c != 0) return c;
    if (a.prerelease.size() == b.prerelease.size()) return 0;
    return a.prerelease.size() < b.prerelease.size() ? -1 : 1;
}

std::string toString(const Version& v)
{
    std::string out{ std::to_string(v.major) + '.' + std::to_string(v.minor) + '.' + std::to_string(v.patch) };
    if (!v.prerelease.empty()) out += '-' + joined(v.prerelease);
    if (!v.build.empty()) out += '+' + joined(v.build);
    return out;
}

bool satisfies(const Version& v, std::string_view range)
{
    bool any{ false };
    bool ok{ true };
    std::size_t at{ 0 };
    while (at < range.size())
    {
        if (range[at] == ' ') { ++at; continue; }
        std::size_t end{ range.find(' ', at) };
        if (end == std::string_view::npos) end = range.size();
        std::string_view token{ range.substr(at, end - at) };
        at = end;
        any = true;

        std::string_view op;
        for (std::string_view candidate : { ">=", "<=", ">", "<", "=", "^", "~" })
            if (token.starts_with(candidate)) { op = candidate; break; }
        if (op.empty()) throw std::invalid_argument("comparator without an operator");
        const auto base{ parseVersion(token.substr(op.size())) };
        if (!base) throw std::invalid_argument("invalid version in range");
        const int c{ compareVersions(v, *base) };

        if (op == "=") ok = ok && c == 0;
        else if (op == ">") ok = ok && c > 0;
        else if (op == ">=") ok = ok && c >= 0;
        else if (op == "<") ok = ok && c < 0;
        else if (op == "<=") ok = ok && c <= 0;
        else
        {
            Version upper{};
            if (op == "~") upper = { base->major, base->minor + 1, 0, {}, {} };
            else if (base->major > 0) upper = { base->major + 1, 0, 0, {}, {} };
            else if (base->minor > 0) upper = { 0, base->minor + 1, 0, {}, {} };
            else upper = { 0, 0, base->patch + 1, {}, {} };
            ok = ok && c >= 0 && compareVersions(v, upper) < 0;
        }
    }
    if (!any) throw std::invalid_argument("empty range");
    return ok;
}

unitTests:
#include <stdexcept>
Version V(std::string_view s) {
    const auto v{ parseVersion(s) };
    if (!v) throw std::runtime_error("test version did not parse: " + std::string(s));
    return *v;
}
TEST("valid versions and their parts") {
    const auto a{ parseVersion("1.2.3") };
    CHECK(a.has_value() && a->major == 1 && a->minor == 2 && a->patch == 3 && a->prerelease.empty() && a->build.empty());
    const auto b{ parseVersion("1.0.0-alpha.1+exp.sha.5114f85") };
    CHECK(b.has_value() && b->prerelease == (std::vector<std::string>{ "alpha", "1" }) && b->build == (std::vector<std::string>{ "exp", "sha", "5114f85" }));
    for (std::string_view ok : { "0.0.0", "10.20.30", "1.0.0-0", "1.0.0-0a", "1.0.0-x-y-z.--", "1.0.0+001", "1.0.0-rc.1+build.1", "18446744073709551615.0.0" })
        CHECK(parseVersion(ok).has_value());
}
TEST("invalid versions") {
    for (std::string_view bad : { "", "1", "1.2", "1.2.3.4", "01.2.3", "1.02.3", "1.2.03", "1.2.3-", "1.2.3+", "1.2.3-01",
                                  "1.2.3-a..b", "1.2.3+a..b", "v1.2.3", " 1.2.3", "1.2.3 ", "1.2.3-a_b", "1.2.3+a b", "1.2.-3",
                                  "a.b.c", "18446744073709551616.0.0", "1..3" })
        CHECK(!parseVersion(bad).has_value());
}
TEST("writing versions back") {
    for (std::string_view s : { "1.2.3", "0.0.0-0", "1.0.0-alpha.1+exp.sha.5114f85", "2.0.0+001", "1.0.0-x-y-z.--" })
        CHECK_EQ(toString(V(s)), std::string(s));
}
TEST("precedence of the core") {
    CHECK_EQ(compareVersions(V("1.0.0"), V("2.0.0")), -1);
    CHECK_EQ(compareVersions(V("2.1.0"), V("2.0.9")), 1);
    CHECK_EQ(compareVersions(V("2.1.1"), V("2.1.10")), -1);
    CHECK_EQ(compareVersions(V("3.0.0"), V("3.0.0")), 0);
}
TEST("the specification's pre-release chain") {
    const char* chain[]{ "1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta", "1.0.0-beta.2", "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0" };
    for (std::size_t i{ 0 }; i + 1 < std::size(chain); ++i) {
        CHECK_EQ(compareVersions(V(chain[i]), V(chain[i + 1])), -1);
        CHECK_EQ(compareVersions(V(chain[i + 1]), V(chain[i])), 1);
    }
}
TEST("more precedence details") {
    CHECK_EQ(compareVersions(V("1.0.0-2"), V("1.0.0-10")), -1);
    CHECK_EQ(compareVersions(V("1.0.0-10"), V("1.0.0-a")), -1);
    CHECK_EQ(compareVersions(V("1.0.0-B"), V("1.0.0-a")), -1);
    CHECK_EQ(compareVersions(V("1.0.0-a.1"), V("1.0.0-a.1.0")), -1);
    CHECK_EQ(compareVersions(V("1.0.0+a"), V("1.0.0+b")), 0);
    CHECK_EQ(compareVersions(V("1.0.0-rc.1+x"), V("1.0.0-rc.1")), 0);
    CHECK_EQ(compareVersions(V("18446744073709551615.0.0"), V("9.0.0")), 1);
}
TEST("simple comparators") {
    CHECK(satisfies(V("1.2.3"), "=1.2.3"));
    CHECK(satisfies(V("1.2.3+build"), "=1.2.3"));
    CHECK(satisfies(V("1.5.0"), ">=1.2.3 <2.0.0"));
    CHECK(!satisfies(V("2.0.0"), ">=1.2.3 <2.0.0"));
    CHECK(satisfies(V("1.2.4"), ">1.2.3"));
    CHECK(!satisfies(V("1.2.3"), ">1.2.3"));
    CHECK(satisfies(V("1.2.3"), "<=1.2.3   >=1.0.0"));
    CHECK(satisfies(V("1.2.3-beta"), "<1.2.3"));
}
TEST("tilde and caret") {
    CHECK(satisfies(V("1.2.9"), "~1.2.3"));
    CHECK(!satisfies(V("1.3.0"), "~1.2.3"));
    CHECK(!satisfies(V("1.2.2"), "~1.2.3"));
    CHECK(satisfies(V("1.9.0"), "^1.2.3"));
    CHECK(!satisfies(V("2.0.0"), "^1.2.3"));
    CHECK(satisfies(V("2.0.0-alpha"), "^1.2.3"));
    CHECK(satisfies(V("0.2.9"), "^0.2.3"));
    CHECK(!satisfies(V("0.3.0"), "^0.2.3"));
    CHECK(satisfies(V("0.0.3"), "^0.0.3"));
    CHECK(!satisfies(V("0.0.4"), "^0.0.3"));
    CHECK(!satisfies(V("1.2.3-rc.1"), "^1.2.3"));
}
TEST("malformed ranges") {
    CHECK_THROWS_AS(satisfies(V("1.0.0"), ""), std::invalid_argument);
    CHECK_THROWS_AS(satisfies(V("1.0.0"), "   "), std::invalid_argument);
    CHECK_THROWS_AS(satisfies(V("1.0.0"), "1.0.0"), std::invalid_argument);
    CHECK_THROWS_AS(satisfies(V("1.0.0"), ">=1.0"), std::invalid_argument);
    CHECK_THROWS_AS(satisfies(V("1.0.0"), ">= 1.0.0"), std::invalid_argument);
}

